CREATE TABLE roles(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(60) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE permissions(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE users(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('super_admin','admin','editor','premium_user','free_user') NOT NULL DEFAULT 'free_user',email_verified_at TIMESTAMP NULL,credits INT NOT NULL DEFAULT 5,remember_token VARCHAR(100) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_users_role(role)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE settings(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,scope VARCHAR(80) NOT NULL,`key` VARCHAR(120) NOT NULL,`value` JSON NOT NULL,UNIQUE KEY uq_settings(scope,`key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE plugins(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL UNIQUE,slug VARCHAR(120) NOT NULL UNIQUE,version VARCHAR(40) NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,config JSON NOT NULL,installed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE api_keys(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,key_hash CHAR(64) NOT NULL UNIQUE,last_used_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE tool_runs(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NULL,ip VARBINARY(16) NOT NULL,tool VARCHAR(120) NOT NULL,input MEDIUMTEXT NOT NULL,output JSON NOT NULL,score TINYINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_tool_runs_user_created(user_id,created_at),INDEX idx_tool_runs_tool(tool)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE credits(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,amount INT NOT NULL,reason VARCHAR(190) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_credits_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE notifications(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(190) NOT NULL,body TEXT NOT NULL,read_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE contacts(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,message TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE audit_logs(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NULL,action VARCHAR(120) NOT NULL,entity VARCHAR(120) NOT NULL,entity_id BIGINT UNSIGNED NULL,metadata JSON NOT NULL,ip VARBINARY(16) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_audit_entity(entity,entity_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE analytics_events(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NULL,event VARCHAR(120) NOT NULL,properties JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_analytics_event_created(event,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE reports(id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,tool_run_id BIGINT UNSIGNED NOT NULL,title VARCHAR(190) NOT NULL,path VARCHAR(255) NOT NULL,format ENUM('pdf','csv') NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(tool_run_id) REFERENCES tool_runs(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
